@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def get_in_patient_checkbox_status() -> opt[bool]:
    """Locates the main Historic Site Setup window > then returns the status of the In Patient checkbox if found
    """
    if __find_main_window():
        if CommonActions.find_object(HistoricSiteSetupObjects.in_Patient_Checkbox) is not None:
            obj = CommonActions.find_object(HistoricSiteSetupObjects.in_Patient_Checkbox)
            return obj.nativeObject.Checked #type: ignore

@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def check_in_patient_checkbox() -> opt[str]:
    """Locates the main Historic Site Setup window > then checks the In Patient checkbox if found
    """
    if __find_main_window():
        if CommonActions.find_object(HistoricSiteSetupObjects.in_Patient_Checkbox) is not None:
            obj = CommonActions.find_object(HistoricSiteSetupObjects.in_Patient_Checkbox)
            if obj.nativeObject.Checked == False: #type: ignore
                CommonActions.left_click_object_no_move(HistoricSiteSetupObjects.in_Patient_Checkbox)

@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def uncheck_in_patient_checkbox() -> opt[str]:
    """Locates the main Historic Site Setup window > then unchecks the In Patient checkbox if found
    """
    if __find_main_window():
        if CommonActions.find_object(HistoricSiteSetupObjects.in_Patient_Checkbox) is not None:
            obj = CommonActions.find_object(HistoricSiteSetupObjects.in_Patient_Checkbox)
            if obj.nativeObject.Checked == True: #type: ignore
                CommonActions.left_click_object_no_move(HistoricSiteSetupObjects.in_Patient_Checkbox)

